package ca.stewark.helioflux.ui.solaractivity
import androidx.compose.foundation.layout.*;import androidx.compose.material3.Text;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.layout.onSizeChanged;import androidx.compose.ui.unit.IntOffset;import ca.stewark.helioflux.core.data.repository.RepositoryState;import ca.stewark.helioflux.core.model.*;import kotlin.math.roundToInt
data class NormalizedRegionPosition(val x:Double,val y:Double)
fun mapActiveRegion(xArcsec:Double,yArcsec:Double)=NormalizedRegionPosition(((512.0+xArcsec/1000.0*512.0)/1024.0).coerceIn(0.0,1.0),((512.0-yArcsec/1000.0*512.0)/1024.0).coerceIn(0.0,1.0))
@Composable fun MagnetogramCard(state:RepositoryState<SolarImage>,regions:List<ActiveRegion>,onClick:()->Unit){Box{SolarImageryCard("HMI Magnetogram","SDO / HMI",state,onClick);var width by remember{mutableIntStateOf(0)};var height by remember{mutableIntStateOf(0)};Box(Modifier.fillMaxSize().onSizeChanged{width=it.width;height=it.height}){regions.forEach{region->val p=mapActiveRegion(region.helioprojectiveX,region.helioprojectiveY);Text(region.number?:region.id,Modifier.offset{IntOffset((p.x*width).roundToInt(),(p.y*height).roundToInt())})}}}}
